unsafe fn BrotliParseAsUTF8(
    mut symbol: *mut c_int,
    mut input: *const uint8_t,
    mut size: size_t,
) -> size_t {
    let b0 = {
        // SAFETY: The original function unconditionally reads input[0], so callers must provide at least one readable byte.
        *input as c_int
    };

    if b0 & 0x80 == 0 {
        *symbol = b0;
        if b0 > 0 {
            return 1 as size_t;
        }
    }

    if size > 1 as size_t {
        let b1 = {
            // SAFETY: This branch is only taken when size > 1, matching the original bounds check before reading input[1].
            *input.add(1) as c_int
        };
        if b0 & 0xe0 == 0xc0 && b1 & 0xc0 == 0x80 {
            let s = ((b0 & 0x1f) << 6) | (b1 & 0x3f);
            *symbol = s;
            if s > 0x7f {
                return 2 as size_t;
            }
        }

        if size > 2 as size_t {
            let b2 = {
                // SAFETY: This branch is only taken when size > 2, matching the original bounds check before reading input[2].
                *input.add(2) as c_int
            };
            if b0 & 0xf0 == 0xe0 && b1 & 0xc0 == 0x80 && b2 & 0xc0 == 0x80 {
                let s = ((b0 & 0xf) << 12) | ((b1 & 0x3f) << 6) | (b2 & 0x3f);
                *symbol = s;
                if s > 0x7ff {
                    return 3 as size_t;
                }
            }

            if size > 3 as size_t {
                let b3 = {
                    // SAFETY: This branch is only taken when size > 3, matching the original bounds check before reading input[3].
                    *input.add(3) as c_int
                };
                if b0 & 0xf8 == 0xf0
                    && b1 & 0xc0 == 0x80
                    && b2 & 0xc0 == 0x80
                    && b3 & 0xc0 == 0x80
                {
                    let s = ((b0 & 0x7) << 18)
                        | ((b1 & 0x3f) << 12)
                        | ((b2 & 0x3f) << 6)
                        | (b3 & 0x3f);
                    *symbol = s;
                    if s > 0xffff && s <= 0x10ffff {
                        return 4 as size_t;
                    }
